// Upstream: apis/file_test.go (TestConcurrentThumbsGeneration)
//
// The file API through the compiled executable, on copies of the vendored
// fixture: concurrent thumb requests (one thumb per path, all generated by
// the worker pool inside the executable), the generated thumb's storage
// (thumbs_<name>/<size>_<name> with its .attrs) and its reuse, and the
// fallbacks to the original. test/differential/files/serve.test.ts
// compares the same paths with upstream.

import { afterEach, expect, test } from "bun:test";
import { existsSync, mkdtempSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import type { FileField } from "@/fields/file";

import { copyDataDir, fixtureDir } from "@test/scenarios/fixture";
import { updateCollection } from "@test/scenarios/prepare";
import { startServer, type RunningServer } from "@test/support/executable";

const roots: string[] = [];
const servers: RunningServer[] = [];

afterEach(async () => {
  for (const server of servers.splice(0)) {
    await server.stop();
  }
  for (const root of roots.splice(0)) {
    rmSync(root, { recursive: true, force: true });
  }
});

function fixtureCopy(): string {
  const root = mkdtempSync(join(tmpdir(), "iglo-base-files-"));
  roots.push(root);
  const dataDir = join(root, "pb_data");
  copyDataDir(fixtureDir, dataDir);
  return dataDir;
}

async function start(dataDir: string, env: Record<string, string> = {}): Promise<string> {
  const server = await startServer([], dataDir, "127.0.0.1", undefined, env);
  servers.push(server);
  return server.url;
}

const fileKey = "wsmn24bux7wo113/al1h9ijdeojtsjy/300_Jsjq7RdBgA.png";

// demo1's file_one: public, with the three new thumb sizes of the Go test
function prepareDemo1Thumbs(dataDir: string): void {
  updateCollection(dataDir, "demo1", (collection) => {
    const fileField = collection.fields.getByName("file_one") as FileField;
    fileField.protected = false;
    fileField.maxSelect = 1;
    fileField.maxSize = 999999;
    // new thumbs
    fileField.thumbs = ["111x111", "111x222", "111x333"];
  });
}

test("TestConcurrentThumbsGeneration", async () => {
  const dataDir = fixtureCopy();
  prepareDemo1Thumbs(dataDir);
  const url = await start(dataDir);

  const urls = [
    "/api/files/" + fileKey + "?thumb=111x111",
    "/api/files/" + fileKey + "?thumb=111x111", // should still result in single thumb
    "/api/files/" + fileKey + "?thumb=111x222",
    "/api/files/" + fileKey + "?thumb=111x333",
  ];
  const responses = await Promise.all(urls.map((u) => fetch(url + u)));
  for (const res of responses) {
    expect(res.status).toBe(200);
    await res.arrayBuffer();
  }

  // ensure that all new requested thumbs were created
  for (const size of ["111x111", "111x222", "111x333"]) {
    const thumb = join(
      dataDir,
      "storage/wsmn24bux7wo113/al1h9ijdeojtsjy/thumbs_300_Jsjq7RdBgA.png",
      `${size}_300_Jsjq7RdBgA.png`,
    );
    expect(existsSync(thumb)).toBe(true);
    const attrs = JSON.parse(readFileSync(thumb + ".attrs", "utf8")) as Record<string, unknown>;
    expect(attrs["user.content_type"]).toBe("image/png");
    // no metadata: json/v2 writes the nil map as {}
    expect(attrs["user.metadata"]).toEqual({});
  }
});

test("a generated thumb is stored once and then served from storage", async () => {
  const dataDir = fixtureCopy();
  prepareDemo1Thumbs(dataDir);
  const url = await start(dataDir);
  const thumb = join(
    dataDir,
    "storage/wsmn24bux7wo113/al1h9ijdeojtsjy/thumbs_300_Jsjq7RdBgA.png/111x222_300_Jsjq7RdBgA.png",
  );

  const first = await fetch(url + "/api/files/" + fileKey + "?thumb=111x222");
  expect(first.status).toBe(200);
  expect(first.headers.get("content-type")).toBe("image/png");
  expect(first.headers.get("content-disposition")).toBe(
    'inline; filename="111x222_300_Jsjq7RdBgA.png"',
  );
  expect(first.headers.get("x-frame-options")).toBeNull();
  const body = new Uint8Array(await first.arrayBuffer());
  expect(Buffer.from(body).equals(readFileSync(thumb))).toBe(true);
  const stored = statSync(thumb).mtimeMs;

  // a second request reads the stored thumb; a changed stored thumb is
  // served as it is
  writeFileSync(thumb, readFileSync(join(dataDir, "storage", fileKey)));
  const second = await fetch(url + "/api/files/" + fileKey + "?thumb=111x222");
  expect(Buffer.from(await second.arrayBuffer())).toEqual(
    readFileSync(join(dataDir, "storage", fileKey)),
  );
  expect(statSync(thumb).mtimeMs).toBeGreaterThanOrEqual(stored);
});

test("thumbs that cannot be made serve the original", async () => {
  const dataDir = fixtureCopy();
  prepareDemo1Thumbs(dataDir);
  // a corrupt PNG in place of the original (its .attrs still says image/png)
  const original = join(dataDir, "storage", fileKey);
  const bytes = readFileSync(original);
  writeFileSync(original, bytes.subarray(0, 40));
  const url = await start(dataDir, { PB_THUMBS_MAX_SOURCE_PIXELS: "" });

  const res = await fetch(url + "/api/files/" + fileKey + "?thumb=111x111");
  expect(res.status).toBe(200);
  expect(res.headers.get("content-disposition")).toBe('inline; filename="300_Jsjq7RdBgA.png"');
  expect(Buffer.from(await res.arrayBuffer())).toEqual(bytes.subarray(0, 40));
  expect(
    existsSync(
      join(
        dataDir,
        "storage/wsmn24bux7wo113/al1h9ijdeojtsjy/thumbs_300_Jsjq7RdBgA.png/111x111_300_Jsjq7RdBgA.png",
      ),
    ),
  ).toBe(false);
});

test("an original over PB_THUMBS_MAX_SOURCE_PIXELS is served as it is", async () => {
  const dataDir = fixtureCopy();
  prepareDemo1Thumbs(dataDir);
  const url = await start(dataDir, { PB_THUMBS_MAX_SOURCE_PIXELS: "10" });

  const res = await fetch(url + "/api/files/" + fileKey + "?thumb=111x111");
  expect(res.status).toBe(200);
  expect(Buffer.from(await res.arrayBuffer())).toEqual(
    readFileSync(join(dataDir, "storage", fileKey)),
  );
});

test("Range, conditional requests and download=1", async () => {
  const dataDir = fixtureCopy();
  prepareDemo1Thumbs(dataDir);
  const url = await start(dataDir);
  const full = readFileSync(join(dataDir, "storage", fileKey));
  const target = url + "/api/files/" + fileKey;

  const plain = await fetch(target);
  const lastModified = plain.headers.get("last-modified") as string;
  expect(lastModified).toMatch(/^[A-Z][a-z]{2}, \d{2} [A-Z][a-z]{2} \d{4} \d{2}:\d{2}:\d{2} GMT$/);
  expect(plain.headers.get("accept-ranges")).toBe("bytes");
  await plain.arrayBuffer();

  const range = await fetch(target, { headers: { Range: "bytes=10-19" } });
  expect(range.status).toBe(206);
  expect(range.headers.get("content-range")).toBe(`bytes 10-19/${full.length}`);
  expect(Buffer.from(await range.arrayBuffer())).toEqual(full.subarray(10, 20));

  const notModified = await fetch(target, { headers: { "If-Modified-Since": lastModified } });
  expect(notModified.status).toBe(304);
  expect(notModified.headers.get("content-type")).toBeNull();
  await notModified.arrayBuffer();

  const old = await fetch(target, {
    headers: { "If-Modified-Since": "Mon, 01 Jan 2001 00:00:00 GMT" },
  });
  expect(old.status).toBe(200);
  await old.arrayBuffer();

  const unsatisfiable = await fetch(target, { headers: { Range: `bytes=${full.length}-` } });
  expect(unsatisfiable.status).toBe(416);
  expect(unsatisfiable.headers.get("content-range")).toBe(`bytes */${full.length}`);
  await unsatisfiable.arrayBuffer();

  const download = await fetch(target + "?download=1");
  expect(download.headers.get("content-disposition")).toBe(
    'attachment; filename="300_Jsjq7RdBgA.png"',
  );
  await download.arrayBuffer();
});
